// Data access layer with two modes sharing one component model:
//
//   * static  (default) — validated JSON indexes generated by
//     scripts/generate_web_data.py from real .tooltrace bundles; works on
//     GitHub Pages with no backend.
//   * server — a self-hosted ToolTrace coordinator (tooltrace server):
//     versioned REST under /api/v1 plus SSE progress at /api/v1/events.
//
// No fabricated data anywhere: if an index is missing, pages show empty
// states. Workspace console demo previews are clearly labeled DEMO.

export interface TaskSummary {
  id: string
  version: string
  category: string
  difficulty: string
  tags: string[]
  max_steps: number
  perturbations: string[]
}

/**
 * Where a failure happened, not just what class it was.
 *
 * A failure category tells a reader that something went wrong. It does not tell
 * them where to look. `seq` and `tool` name the exact trace event the
 * classification came from, which is what makes a cluster openable at the step
 * that broke instead of at the top of a trace.
 *
 * Null on a run that did not fail — attributing a step on a passing run would
 * invent a defect.
 */
export interface FailureStep {
  seq: number | null
  tool: string | null
  reason: string
  rule: string
  detail: string
}

export interface ResultRow {
  bundle: string
  task_id: string
  task_version: string
  agent: string
  success: boolean
  partial_success: boolean
  score_total: number
  steps: number
  tool_calls: number
  failed_tool_calls: number
  invalid_tool_calls: number
  repeated_calls: number
  unnecessary_changes: number
  workspace_violations: number
  wall_ms: number
  model_ms: number | null
  tool_ms: number
  failure_reason: string
  trust_state: string
  run_id: string
  created_at: string
  /** Absent on older generated indexes, null on a run that did not fail. */
  failure_step?: FailureStep | null
}

export interface AgentRow {
  name: string
  runs: number
  success_rate: number
  mean_score: number
  mean_steps: number
  failed_tool_calls_mean: number
  wall_ms_p95: number
  /**
   * The cost and security axes. Null means *not measured*, never zero: an
   * unmeasured cost rendered as 0 would read as free, and an unmeasured attack
   * success rate as perfectly secure. Both are the most misleading numbers this
   * dashboard could show, so the UI renders them as "not measured".
   */
  cost_per_resolved_task: number | null
  total_cost: number | null
  priced_runs: number
  currency: string | null
  attack_success_rate: number | null
  security_runs: number
  /** Wilson 95% interval on the attack-success rate; null when unmeasured. */
  attack_ci95?: [number, number] | null
  /**
   * Under 30 attempts. A 0% attack-success rate over four attempts has an
   * upper bound near 50%, so the flag is not decoration: without it the number
   * reads as a secure agent when it is barely evidence at all.
   */
  security_sample_is_small?: boolean
}

/** One rate with its interval — the shape `metrics/security.py` returns. */
export interface RateBlock {
  attempts: number
  attacks_succeeded: number
  attack_success_rate: number | null
  ci95: [number, number] | null
  sample_is_small: boolean
}

export interface SecurityRun {
  bundle: string
  task_id: string
  agent: string
  created_at: string
  /** The scorers score the *defence*, so this is the inversion, done once. */
  attack_succeeded: boolean
  attack_class: string
  vector: string
  owasp: string
}

export interface SecurityPosture extends RateBlock {
  generated_at: string
  by_class: Record<string, RateBlock>
  by_agent: Record<string, RateBlock>
  runs: SecurityRun[]
}

export interface ObligationEvidence {
  article: string
  title: string
  evidence: string[]
  /** Never empty by construction — an obligation with no stated gap would
   * read as fully satisfied, which this project is not entitled to assert. */
  gaps: string[]
}

export interface EvidenceRun {
  bundle: string
  verified: boolean
  verification_problems: string[]
  task_id: string
  task_version: string
  agent: string
  run_id: string
  success: boolean
  score: number | null
  failure_reason: string | null
  created_at: string
  framework_version: string
  compatibility_key: string
  trust_state: string
  manifest_sha256: string
}

export interface EvidenceDossier {
  schema: string
  generated_at: string
  statement: string
  runs: EvidenceRun[]
  obligations: ObligationEvidence[]
  hash_chain: { bundle: string; previous: string; entry: string }[]
  chain_head: string
}

export interface IndexData {
  generated_at: string
  framework_version: string
  compatibility_key: string
  counts: { tasks: number; results: number; agents: number; packs: number }
}

// ---------- server-mode configuration ----------

const SERVER_URL_KEY = 'ttb-server-url'
const SERVER_TOKEN_KEY = 'ttb-token'

export function getServerUrl(): string {
  return localStorage.getItem(SERVER_URL_KEY) ?? ''
}

export function setServerUrl(url: string): void {
  if (url) localStorage.setItem(SERVER_URL_KEY, url.replace(/\/+$/, ''))
  else localStorage.removeItem(SERVER_URL_KEY)
}

/** Token lives only in the session owner's browser; it is never logged,
 * never embedded in URLs and never persisted into traces or reports. */
export function getServerToken(): string {
  return localStorage.getItem(SERVER_TOKEN_KEY) ?? ''
}

export function setServerToken(token: string): void {
  if (token) localStorage.setItem(SERVER_TOKEN_KEY, token)
  else localStorage.removeItem(SERVER_TOKEN_KEY)
}

export function isServerMode(): boolean {
  return getServerUrl() !== ''
}

async function fetchJson<T>(url: string, init?: RequestInit): Promise<T> {
  const res = await fetch(url, init)
  if (!res.ok) throw new Error(`${url}: HTTP ${res.status}`)
  return (await res.json()) as T
}

/**
 * Resolve a path to a file shipped with the site.
 *
 * These were passed to `fetch` as bare relative strings — `data/results.json`,
 * `bundles/<name>/trace.json` — which the browser resolves against the current
 * route, not the site root. From `/results/<bundle>` that asks for
 * `/results/data/results.json`. Every dataset load on every nested route was a
 * 404, and the pages showed their empty state as if the dataset were empty.
 *
 * `import.meta.env.BASE_URL` is the deploy prefix Vite was built with and
 * always ends in a slash, so this is correct at the root, under a GitHub Pages
 * project subpath, and at any route depth.
 */
export function assetUrl(path: string): string {
  return `${import.meta.env.BASE_URL}${path.replace(/^\/+/, '')}`
}

function withBase(path: string): string {
  // Dataset files always come from the site itself, never from a connected
  // team server: they are the published, checksummed artifacts.
  if (path.startsWith('data/') || path.startsWith('bundles/')) return assetUrl(path)
  const base = getServerUrl()
  if (!base) return path
  return `${base}${path}`
}

function withAuth(init?: RequestInit): RequestInit {
  const token = getServerToken()
  if (!token) return init ?? {}
  const headers = new Headers(init?.headers)
  headers.set('Authorization', `Bearer ${token}`)
  return { ...init, headers }
}

/** GET JSON from the active backend (static indexes or team server). */
export async function apiGet<T>(path: string): Promise<T> {
  return fetchJson<T>(withBase(path), withAuth())
}

/** POST JSON to the team server. Rejects in static mode. */
export async function apiPost<T>(path: string, body: unknown): Promise<T> {
  if (!isServerMode()) throw new Error('Requires a connected ToolTrace server.')
  return fetchJson<T>(
    withBase(path),
    withAuth({
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    }),
  )
}

/** Subscribe to live experiment progress over SSE (server mode only).
 * Returns a disconnect function; no-op in static mode. */
export function subscribeEvents(onEvent: (e: MessageEvent) => void): () => void {
  if (!isServerMode()) return () => undefined
  const es = new EventSource(withBase('/api/v1/events'))
  es.onmessage = onEvent
  return () => es.close()
}

// ---------- public dataset loaders (work in both modes) ----------

export const getIndex = () => apiGet<IndexData>('data/index.json')
export const getTasks = () => apiGet<TaskSummary[]>('data/tasks.json')
export const getResults = () => apiGet<ResultRow[]>('data/results.json')
export const getAgents = () => apiGet<AgentRow[]>('data/agents.json')
export const getSecurity = () => apiGet<SecurityPosture>('data/security.json')
export const getEvidence = () => apiGet<EvidenceDossier>('data/evidence.json')

// ---------- team-server resource types (server mode) ----------

export interface ExperimentRow {
  id: string
  status: string
  workspace_id?: string
  suite_id?: string
  agent_adapter?: string
  repetitions?: number
  created_at?: string
  [key: string]: unknown
}

export interface ApprovalRow {
  request_id: string
  workspace_id: string
  action: string
  state: string
  requested_by?: string
  decided_by?: string | null
}

export interface AuditRow {
  seq: number
  actor: string
  action: string
  target: string
  at: string
  prev_hash?: string
  hash?: string
}

export interface HealthInfo {
  healthz: boolean
  readyz: boolean
  metricsText: string
}

export async function listExperiments(): Promise<ExperimentRow[]> {
  const d = await apiGet<{ experiments: ExperimentRow[] }>('/api/v1/experiments')
  return d.experiments
}

export async function fetchHealth(): Promise<HealthInfo> {
  const healthz = await fetchJson<{ status: string }>(withBase('/healthz'))
    .then(() => true)
    .catch(() => false)
  const readyz = await fetchJson<{ ready: boolean }>(withBase('/readyz'))
    .then((d) => Boolean(d.ready))
    .catch(() => false)
  const metricsText = await fetchJson<{ _text: string }>(withBase('/metrics'))
    .then((m) => m._text)
    .catch(() => '')
  return { healthz, readyz, metricsText }
}

import { useEffect, useState } from 'react'

export interface AsyncState<T> {
  data: T | null
  loading: boolean
  error: string | null
}

export function useAsync<T>(fn: () => Promise<T>, deps: unknown[] = []): AsyncState<T> {
  const [data, setData] = useState<T | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  useEffect(() => {
    let alive = true
    setLoading(true)
    setError(null)
    fn()
      .then((d) => {
        if (alive) setData(d)
      })
      .catch((e: unknown) => {
        if (alive) setError(e instanceof Error ? e.message : String(e))
      })
      .finally(() => {
        if (alive) setLoading(false)
      })
    return () => {
      alive = false
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps)
  return { data, loading, error }
}
